CREATE TABLE `clients` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `client_number` varchar(30) NOT NULL,
  `full_name` varchar(255) NOT NULL,
  `document_type` varchar(20) NOT NULL DEFAULT 'bi',
  `document_number` varchar(50) NOT NULL,
  `document_expiry` date DEFAULT NULL,
  `nuit` varchar(20) DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `nationality` varchar(60) DEFAULT NULL,
  `phone` varchar(30) NOT NULL,
  `phone_alt` varchar(30) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `occupation` varchar(255) DEFAULT NULL,
  `monthly_income` decimal(15,2) DEFAULT NULL,
  `emergency_contact_name` varchar(255) DEFAULT NULL,
  `emergency_contact_phone` varchar(30) DEFAULT NULL,
  `emergency_contact_relationship` varchar(60) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `kyc_status` varchar(20) NOT NULL DEFAULT 'pending',
  `kyc_verified_by` bigint(20) unsigned DEFAULT NULL,
  `kyc_verified_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `is_demo` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `clients_document_type_document_number_unique` (`document_type`,`document_number`),
  UNIQUE KEY `clients_client_number_unique` (`client_number`),
  UNIQUE KEY `clients_user_id_unique` (`user_id`),
  UNIQUE KEY `clients_nuit_unique` (`nuit`),
  KEY `clients_kyc_verified_by_foreign` (`kyc_verified_by`),
  KEY `clients_created_by_foreign` (`created_by`),
  KEY `clients_full_name_index` (`full_name`),
  KEY `clients_email_index` (`email`),
  KEY `clients_status_index` (`status`),
  KEY `clients_kyc_status_index` (`kyc_status`),
  CONSTRAINT `clients_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `clients_kyc_verified_by_foreign` FOREIGN KEY (`kyc_verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `clients_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
