CREATE TABLE `collaterals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_application_id` bigint(20) unsigned NOT NULL,
  `loan_id` bigint(20) unsigned DEFAULT NULL,
  `type` varchar(40) NOT NULL,
  `description` varchar(255) NOT NULL,
  `estimated_value` decimal(15,2) NOT NULL,
  `ownership_document` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'declared',
  `verified_by` bigint(20) unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `collaterals_loan_application_id_foreign` (`loan_application_id`),
  KEY `collaterals_loan_id_foreign` (`loan_id`),
  KEY `collaterals_verified_by_foreign` (`verified_by`),
  CONSTRAINT `collaterals_loan_application_id_foreign` FOREIGN KEY (`loan_application_id`) REFERENCES `loan_applications` (`id`) ON DELETE CASCADE,
  CONSTRAINT `collaterals_loan_id_foreign` FOREIGN KEY (`loan_id`) REFERENCES `loans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `collaterals_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
