me_unfavorable\":12,\"max_active_loans\":2}','{\"monthly_income\":\"25000.00\",\"other_income\":\"0.00\",\"monthly_expenses\":\"8750.00\",\"existing_obligations\":\"0.00\",\"installment\":\"682.71\",\"frequency\":\"weekly\",\"principal\":\"5000.00\",\"outstanding_exposure\":\"0.00\",\"active_loans\":0,\"worst_days_overdue\":5,\"previous_loans\":1,\"monthly_installment_equivalent\":\"2958.41\",\"total_monthly_income\":\"25000.00\"}','[{\"key\":\"installment_to_income\",\"label\":\"Rela\\u00e7\\u00e3o presta\\u00e7\\u00e3o\\/rendimento\",\"value\":\"11,83%\",\"threshold\":\"\\u2264 30% (an\\u00e1lise \\u2264 40%)\",\"status\":\"favorable\",\"explanation\":\"A presta\\u00e7\\u00e3o mensal equivalente (2.958,41 MZN) representa 11,83% do rendimento.\"},{\"key\":\"debt_service\",\"label\":\"Taxa de esfor\\u00e7o total\",\"value\":\"11,83%\",\"threshold\":\"\\u2264 40% (an\\u00e1lise \\u2264 55%)\",\"status\":\"favorable\",\"explanation\":\"Obriga\\u00e7\\u00f5es mensais (0,00 MZN) mais a nova presta\\u00e7\\u00e3o representam 11,83% do rendimento.\"},{\"key\":\"residual_income\",\"label\":\"Rendimento dispon\\u00edvel ap\\u00f3s a presta\\u00e7\\u00e3o\",\"value\":\"13.291,59 MZN\",\"threshold\":\"\\u2265 0,00 MZN\",\"status\":\"favorable\",\"explanation\":\"Rendimento dispon\\u00edvel estimado de 16.250,00 MZN (rendimento \\u2212 despesas \\u2212 obriga\\u00e7\\u00f5es); ap\\u00f3s a presta\\u00e7\\u00e3o restam 13.291,59 MZN.\"},{\"key\":\"history\",\"label\":\"Pior atraso hist\\u00f3rico\",\"value\":\"5 dias\",\"threshold\":\"\\u2264 15 dias (an\\u00e1lise \\u2264 60 dias)\",\"status\":\"favorable\",\"explanation\":\"Em 1 empr\\u00e9stimo(s) anterior(es)\\/actual(is), o maior atraso registado foi de 5 dia(s).\"},{\"key\":\"exposure\",\"label\":\"Exposi\\u00e7\\u00e3o total \\/ rendimento mensal\",\"value\":\"0,20\\u00d7\",\"threshold\":\"\\u2264 6\\u00d7 (an\\u00e1lise \\u2264 12\\u00d7)\",\"status\":\"favorable\",\"explanation\":\"Capital em d\\u00edvida actual (0,00 MZN) mais o novo capital (5.000,00 MZN) equivale a 0,20 vezes o rendimento mensal.\"},{\"key\":\"active_loans\",\"label\":\"Empr\\u00e9stimos activos\",\"value\":\"0\",\"threshold\":\"< 2\",\"status\":\"favorable\",\"explanation\":\"O cliente tem 0 empr\\u00e9stimo(s) activo(s) na institui\\u00e7\\u00e3o.\"}]','favorable','Todos os indicadores avaliados são favoráveis. Recomendação automática de apoio à decisão; não substitui a decisão do gestor autorizado.',4,'2026-10-10 08:57:00');
