CREATE TABLE `disbursements` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `disbursement_number` varchar(30) NOT NULL,
  `loan_id` bigint(20) unsigned NOT NULL,
  `gross_amount` decimal(15,2) NOT NULL,
  `deducted_fees` decimal(15,2) NOT NULL DEFAULT 0.00,
  `net_amount` decimal(15,2) NOT NULL,
  `method` varchar(30) NOT NULL,
  `destination_account` varchar(100) DEFAULT NULL,
  `reference` varchar(100) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `requested_by` bigint(20) unsigned DEFAULT NULL,
  `requested_at` timestamp NULL DEFAULT NULL,
  `authorized_by` bigint(20) unsigned DEFAULT NULL,
  `authorized_at` timestamp NULL DEFAULT NULL,
  `executed_by` bigint(20) unsigned DEFAULT NULL,
  `disbursed_at` date DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `proof_path` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `cancellation_reason` varchar(255) DEFAULT NULL,
  `active_loan_key` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `disbursements_disbursement_number_unique` (`disbursement_number`),
  UNIQUE KEY `disbursements_method_reference_unique` (`method`,`reference`),
  UNIQUE KEY `disbursements_active_loan_key_unique` (`active_loan_key`),
  KEY `disbursements_loan_id_foreign` (`loan_id`),
  KEY `disbursements_requested_by_foreign` (`requested_by`),
  KEY `disbursements_authorized_by_foreign` (`authorized_by`),
  KEY `disbursements_executed_by_foreign` (`executed_by`),
  KEY `disbursements_status_index` (`status`),
  CONSTRAINT `disbursements_authorized_by_foreign` FOREIGN KEY (`authorized_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `disbursements_executed_by_foreign` FOREIGN KEY (`executed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `disbursements_loan_id_foreign` FOREIGN KEY (`loan_id`) REFERENCES `loans` (`id`),
  CONSTRAINT `disbursements_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

