INSERT INTO `faqs` VALUES (1,'Quem pode pedir crédito?','Pessoas maiores de idade com documento de identificação válido e capacidade de pagamento demonstrada. Cada produto pode ter requisitos adicionais, indicados na respectiva página.',1,1,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(2,'A simulação garante a aprovação?','Não. A simulação é indicativa e utiliza o mesmo cálculo dos contratos, mas a concessão depende da análise do pedido e da decisão de um gestor autorizado.',2,1,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(3,'Que documentos preciso?','Normalmente o documento de identificação, NUIT, comprovativo de residência e comprovativo de rendimentos. A equipa pode pedir documentos adicionais durante a análise.',3,1,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(4,'Como sei em que fase está o meu pedido?','No portal, em «Meus pedidos», pode acompanhar cada etapa. Recebe também notificações quando há novidades.',4,1,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(5,'Como posso pagar as prestações?','Por M-Pesa, e-Mola, transferência ou depósito bancário, ou em numerário no balcão. Depois de pagar, pode submeter o comprovativo no portal; o pagamento é confirmado pela instituição e o recibo fica disponível.',5,1,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(6,'Posso liquidar o empréstimo antes do prazo?','Sim. O montante de liquidação antecipada é calculado de acordo com as condições do contrato. Contacte a instituição para obter o valor actualizado.',6,1,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(7,'O que acontece se me atrasar?','Podem ser aplicadas as penalizações previstas no contrato. Se tiver dificuldades, contacte-nos o quanto antes para avaliarmos uma solução.',7,1,'2026-10-16 12:47:11','2026-10-16 12:47:11');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
