CREATE TABLE `financial_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transaction_number` varchar(30) NOT NULL,
  `loan_id` bigint(20) unsigned NOT NULL,
  `client_id` bigint(20) unsigned NOT NULL,
  `type` varchar(40) NOT NULL,
  `component` varchar(20) NOT NULL,
  `direction` varchar(10) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `source_type` varchar(255) DEFAULT NULL,
  `source_id` bigint(20) unsigned DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `posted_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `financial_transactions_transaction_number_unique` (`transaction_number`),
  KEY `financial_transactions_client_id_foreign` (`client_id`),
  KEY `financial_transactions_created_by_foreign` (`created_by`),
  KEY `financial_transactions_source_type_source_id_index` (`source_type`,`source_id`),
  KEY `financial_transactions_loan_id_component_index` (`loan_id`,`component`),
  KEY `financial_transactions_type_index` (`type`),
  KEY `financial_transactions_posted_at_index` (`posted_at`),
  CONSTRAINT `financial_transactions_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `financial_transactions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `financial_transactions_loan_id_foreign` FOREIGN KEY (`loan_id`) REFERENCES `loans` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

