/*!40000 ALTER TABLE `loan_application_reviews` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `loan_applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `loan_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `application_number` varchar(30) NOT NULL,
  `client_id` bigint(20) unsigned NOT NULL,
  `loan_product_id` bigint(20) unsigned NOT NULL,
  `loan_product_version_id` bigint(20) unsigned NOT NULL,
  `requested_amount` decimal(15,2) NOT NULL,
  `term` smallint(5) unsigned NOT NULL,
  `repayment_frequency` varchar(20) NOT NULL,
  `amortization_method` varchar(30) NOT NULL,
  `purpose` text NOT NULL,
  `monthly_income` decimal(15,2) NOT NULL,
  `other_income` decimal(15,2) NOT NULL DEFAULT 0.00,
  `monthly_expenses` decimal(15,2) NOT NULL DEFAULT 0.00,
  `existing_obligations` decimal(15,2) NOT NULL DEFAULT 0.00,
  `employment_type` varchar(30) DEFAULT NULL,
  `employer_name` varchar(255) DEFAULT NULL,
  `occupation` varchar(255) DEFAULT NULL,
  `simulated_installment` decimal(15,2) DEFAULT NULL,
  `simulated_total` decimal(15,2) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'submitted',
  `assigned_to` bigint(20) unsigned DEFAULT NULL,
  `decided_by` bigint(20) unsigned DEFAULT NULL,
  `decided_at` timestamp NULL DEFAULT NULL,
  `approved_amount` decimal(15,2) DEFAULT NULL,
  `approved_term` smallint(5) unsigned DEFAULT NULL,
  `decision_notes` text DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `info_request` text DEFAULT NULL,
  `consents` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`consents`)),
  `declaration_accepted_at` timestamp NULL DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `loan_applications_application_number_unique` (`application_number`),
  KEY `loan_applications_loan_product_id_foreign` (`loan_product_id`),
  KEY `loan_applications_loan_product_version_id_foreign` (`loan_product_version_id`),
  KEY `loan_applications_assigned_to_foreign` (`assigned_to`),
  KEY `loan_applications_decided_by_foreign` (`decided_by`),
  KEY `loan_applications_created_by_foreign` (`created_by`),
  KEY `loan_applications_client_id_status_index` (`client_id`,`status`),
  KEY `loan_applications_status_index` (`status`),
  CONSTRAINT `loan_applications_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loan_applications_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `loan_applications_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loan_applications_decided_by_foreign` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loan_applications_loan_product_id_foreign` FOREIGN KEY (`loan_product_id`) REFERENCES `loan_products` (`id`),
  CONSTRAINT `loan_applications_loan_product_version_id_foreign` FOREIGN KEY (`loan_product_version_id`) REFERENCES `loan_product_versions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `loan_applications` WRITE;
