/*!40000 ALTER TABLE `loan_applications` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `loan_installments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `loan_installments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_id` bigint(20) unsigned NOT NULL,
  `schedule_version` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `number` smallint(5) unsigned NOT NULL,
  `due_date` date NOT NULL,
  `opening_balance` decimal(15,2) NOT NULL,
  `principal_due` decimal(15,2) NOT NULL,
  `interest_due` decimal(15,2) NOT NULL,
  `fee_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `penalty_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `principal_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `fee_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `penalty_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `interest_waived` decimal(15,2) NOT NULL DEFAULT 0.00,
  `penalty_waived` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_due` decimal(15,2) NOT NULL,
  `total_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `days_overdue` int(10) unsigned NOT NULL DEFAULT 0,
  `paid_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `loan_installments_loan_id_schedule_version_number_unique` (`loan_id`,`schedule_version`,`number`),
  KEY `loan_installments_due_date_status_index` (`due_date`,`status`),
  KEY `loan_installments_status_index` (`status`),
  CONSTRAINT `loan_installments_loan_id_foreign` FOREIGN KEY (`loan_id`) REFERENCES `loans` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

