CREATE TABLE `loan_product_versions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_product_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `min_amount` decimal(15,2) NOT NULL,
  `max_amount` decimal(15,2) NOT NULL,
  `min_term` smallint(5) unsigned NOT NULL,
  `max_term` smallint(5) unsigned NOT NULL,
  `interest_rate` decimal(9,4) NOT NULL,
  `rate_period` varchar(10) NOT NULL,
  `allowed_frequencies` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`allowed_frequencies`)),
  `amortization_methods` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`amortization_methods`)),
  `fees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fees`)),
  `penalty_type` varchar(20) NOT NULL DEFAULT 'none',
  `penalty_value` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `penalty_grace_days` smallint(5) unsigned NOT NULL DEFAULT 0,
  `early_settlement_rule` varchar(40) NOT NULL DEFAULT 'waive_future_interest',
  `eligibility_rules` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`eligibility_rules`)),
  `change_notes` text DEFAULT NULL,
  `effective_from` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `loan_product_versions_loan_product_id_version_unique` (`loan_product_id`,`version`),
  KEY `loan_product_versions_created_by_foreign` (`created_by`),
  CONSTRAINT `loan_product_versions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loan_product_versions_loan_product_id_foreign` FOREIGN KEY (`loan_product_id`) REFERENCES `loan_products` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
