weekly\"]','[\"annuity\",\"flat\"]','[{\"name\":\"Comiss\\u00e3o de abertura\",\"type\":\"percent\",\"value\":\"3.0000\",\"charge\":\"upfront\"}]','percent',5.0000,3,'waive_future_interest','{\"min_monthly_income\":\"5000.00\",\"max_active_loans\":2,\"min_age\":18,\"requires_guarantor\":false,\"requires_collateral\":false}','Revisão da taxa de juro (demonstração).','2026-04-16 08:33:00',2,'2026-04-16 08:33:00','2026-04-16 08:33:00');
