INSERT INTO `loan_products` VALUES (1,'PN','credito-pequeno-negocio','Crédito Pequeno Negócio','Financiamento para reforço de stock, equipamento e fundo de maneio de pequenos negócios formais e informais.\n\nProduto de demonstração — condições ilustrativas, a definir e validar pela instituição.','Documento de identificação válido\nNUIT\nComprovativo de residência\nDescrição da actividade e registo de vendas ou extracto','O mutuário obriga-se a utilizar o crédito para a finalidade declarada e a comunicar à instituição qualquer alteração dos seus contactos ou da sua situação financeira. (Texto de demonstração)','active',1,5,2,'2025-08-16 08:15:00','2026-04-16 08:33:00'),(2,'CS','credito-salarial','Crédito Salarial','Crédito pessoal para trabalhadores por conta de outrem, com prestações mensais ajustadas ao salário.\n\nProduto de demonstração — condições ilustrativas, a definir e validar pela instituição.','Documento de identificação válido\nNUIT\nDeclaração da entidade empregadora\nÚltimos 3 recibos de vencimento ou extracto bancário','O mutuário obriga-se a utilizar o crédito para a finalidade declarada e a comunicar à instituição qualquer alteração dos seus contactos ou da sua situação financeira. (Texto de demonstração)','active',1,2,2,'2025-08-16 08:15:00','2025-08-16 08:15:00'),(3,'MS','microcredito-semanal-mercado','Microcrédito Semanal Mercado','Pequenos montantes com prestações semanais, pensado para vendedores de mercado.\n\nProduto de demonstração — condições ilustrativas, a definir e validar pela instituição.','Documento de identificação válido\nUm fiador\nIndicação do local de venda','O mutuário obriga-se a utilizar o crédito para a finalidade declarada e a comunicar à instituição qualquer alteração dos seus contactos ou da sua situação financeira. (Texto de demonstração)','active',1,3,2,'2025-08-16 08:15:00','2025-08-16 08:15:00'),(4,'CA','credito-agricola-campanha','Crédito Agrícola Campanha','Financiamento de insumos e preparação de terras para a campanha agrícola.\n\nProduto de demonstração — condições ilustrativas, a definir e validar pela instituição.','Documento de identificação válido\nComprovativo da exploração\nGarantia (equipamento, gado ou outro bem)','O mutuário obriga-se a utilizar o crédito para a finalidade declarada e a comunicar à instituição qualquer alteração dos seus contactos ou da sua situação financeira. (Texto de demonstração)','active',1,4,2,'2025-08-16 08:15:00','2025-08-16 08:15:00');
/*!40000 ALTER TABLE `loan_products` ENABLE KEYS */;
