UNLOCK TABLES;
DROP TABLE IF EXISTS `loans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `loans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `loan_number` varchar(30) NOT NULL,
  `contract_number` varchar(30) NOT NULL,
  `client_id` bigint(20) unsigned NOT NULL,
  `loan_application_id` bigint(20) unsigned NOT NULL,
  `loan_product_id` bigint(20) unsigned NOT NULL,
  `loan_product_version_id` bigint(20) unsigned NOT NULL,
  `principal_amount` decimal(15,2) NOT NULL,
  `interest_rate` decimal(9,4) NOT NULL,
  `rate_period` varchar(10) NOT NULL,
  `rate_per_period` decimal(14,10) NOT NULL,
  `repayment_frequency` varchar(20) NOT NULL,
  `amortization_method` varchar(30) NOT NULL,
  `term` smallint(5) unsigned NOT NULL,
  `fees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fees`)),
  `upfront_fees` decimal(15,2) NOT NULL DEFAULT 0.00,
  `financed_fees` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_interest` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_contract_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `penalty_type` varchar(20) NOT NULL DEFAULT 'none',
  `penalty_value` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `penalty_grace_days` smallint(5) unsigned NOT NULL DEFAULT 0,
  `early_settlement_rule` varchar(40) NOT NULL,
  `terms_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`terms_snapshot`)),
  `status` varchar(30) NOT NULL DEFAULT 'awaiting_contract',
  `principal_outstanding` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_paid` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_outstanding` decimal(15,2) NOT NULL DEFAULT 0.00,
  `days_past_due` int(10) unsigned NOT NULL DEFAULT 0,
  `next_due_date` date DEFAULT NULL,
  `first_due_date` date DEFAULT NULL,
  `maturity_date` date DEFAULT NULL,
  `schedule_version` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `contract_signed_at` timestamp NULL DEFAULT NULL,
  `formalized_by` bigint(20) unsigned DEFAULT NULL,
  `signed_contract_path` varchar(255) DEFAULT NULL,
  `disbursed_at` date DEFAULT NULL,
  `settled_at` timestamp NULL DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `loan_officer_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `loans_loan_number_unique` (`loan_number`),
  UNIQUE KEY `loans_contract_number_unique` (`contract_number`),
  UNIQUE KEY `loans_loan_application_id_unique` (`loan_application_id`),
  KEY `loans_loan_product_id_foreign` (`loan_product_id`),
  KEY `loans_loan_product_version_id_foreign` (`loan_product_version_id`),
  KEY `loans_approved_by_foreign` (`approved_by`),
  KEY `loans_formalized_by_foreign` (`formalized_by`),
  KEY `loans_loan_officer_id_foreign` (`loan_officer_id`),
  KEY `loans_client_id_status_index` (`client_id`,`status`),
  KEY `loans_status_index` (`status`),
  KEY `loans_days_past_due_index` (`days_past_due`),
  KEY `loans_next_due_date_index` (`next_due_date`),
  CONSTRAINT `loans_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loans_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `loans_formalized_by_foreign` FOREIGN KEY (`formalized_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loans_loan_application_id_foreign` FOREIGN KEY (`loan_application_id`) REFERENCES `loan_applications` (`id`),
  CONSTRAINT `loans_loan_officer_id_foreign` FOREIGN KEY (`loan_officer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loans_loan_product_id_foreign` FOREIGN KEY (`loan_product_id`) REFERENCES `loan_products` (`id`),
  CONSTRAINT `loans_loan_product_version_id_foreign` FOREIGN KEY (`loan_product_version_id`) REFERENCES `loan_product_versions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

