INSERT INTO `loans` VALUES (1,'EMP-2026-000001','CTR-2026-000001',1,1,1,5,30000.00,4.0000,'monthly',0.0400000000,'monthly','annuity',6,'[{\"name\":\"Comiss\\u00e3o de abertura\",\"type\":\"percent\",\"value\":\"3.0000\",\"charge\":\"upfront\"}]',900.00,0.00,4337.14,34337.14,'percent',5.0000,3,'waive_future_interest','{\"product\":{\"code\":\"PN\",\"name\":\"Cr\\u00e9dito Pequeno Neg\\u00f3cio\",\"version\":2},\"contract_conditions\":\"O mutu\\u00e1rio obriga-se a utilizar o cr\\u00e9dito para a finalidade declarada e a comunicar \\u00e0 institui\\u00e7\\u00e3o qualquer altera\\u00e7\\u00e3o dos seus contactos ou da sua situa\\u00e7\\u00e3o financeira. (Texto de demonstra\\u00e7\\u00e3o)\",\"interest_rate\":\"4.0000\",\"rate_period\":\"monthly\",\"rate_label\":\"4% ao m\\u00eas\",\"frequency\":\"monthly\",\"method\":\"annuity\",\"fees\":[{\"name\":\"Comiss\\u00e3o de abertura\",\"type\":\"percent\",\"value\":\"3.0000\",\"charge\":\"upfront\",\"amount\":\"900.00\"}],\"fees_label\":\"Comiss\\u00e3o de abertura: 3% do capital (deduzido no desembolso)\",\"penalty_label\":\"5% do valor em atraso, uma vez por presta\\u00e7\\u00e3o (ap\\u00f3s 3 dia(s) de car\\u00eancia)\",\"early_settlement_label\":\"Liquida\\u00e7\\u00e3o antecipada sem juros dos per\\u00edodos futuros (apenas juros do per\\u00edodo em curso)\",\"preview_installment\":\"5722.86\",\"approved_at\":\"2026-07-08T10:35:00+02:00\"}','active',15881.44,17168.58,17168.56,0,'2026-11-11','2026-08-11','2027-01-11',1,3,'2026-07-08 08:35:00','2026-07-08 22:00:00',4,NULL,'2026-07-11',NULL,NULL,4,'2026-07-08 08:35:00','2026-10-12 08:23:00'),(2,'EMP-2025-000001','CTR-2025-000001',2,2,2,2,20000.00,3.5000,'monthly',0.0350000000,'monthly','annuity',6,'[{\"name\":\"Comiss\\u00e3o de processamento\",\"type\":\"percent\",\"value\":\"2.0000\",\"charge\":\"upfront\"},{\"name\":\"Seguro de cr\\u00e9dito\",\"type\":\"percent\",\"value\":\"0.5000\",\"charge\":\"financed\"}]',400.00,100.00,2520.18,22620.18,'fixed',250.0000,5,'waive_f