  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `payment_promises_collection_id_foreign` (`collection_id`),
  KEY `payment_promises_loan_id_foreign` (`loan_id`),
  KEY `payment_promises_created_by_foreign` (`created_by`),
  KEY `payment_promises_promised_date_index` (`promised_date`),
  KEY `payment_promises_status_index` (`status`),
  CONSTRAINT `payment_promises_collection_id_foreign` FOREIGN KEY (`collection_id`) REFERENCES `collections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `payment_promises_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payment_promises_loan_id_foreign` FOREIGN KEY (`loan_id`) REFERENCES `loans` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
