  KEY `payments_client_id_foreign` (`client_id`),
  KEY `payments_registered_by_foreign` (`registered_by`),
  KEY `payments_confirmed_by_foreign` (`confirmed_by`),
  KEY `payments_rejected_by_foreign` (`rejected_by`),
  KEY `payments_loan_id_status_index` (`loan_id`,`status`),
  KEY `payments_paid_at_index` (`paid_at`),
  KEY `payments_status_index` (`status`),
  CONSTRAINT `payments_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `payments_confirmed_by_foreign` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_loan_id_foreign` FOREIGN KEY (`loan_id`) REFERENCES `loans` (`id`),
  CONSTRAINT `payments_registered_by_foreign` FOREIGN KEY (`registered_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_rejected_by_foreign` FOREIGN KEY (`rejected_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
