INSERT INTO `system_settings` VALUES (1,'institution','institution.name','SumbaneCredit','string','Nome comercial',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(2,'institution','institution.tagline','Crédito simples, gestão inteligente.','string','Slogan',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(3,'institution','institution.legal_name','','string','Denominação legal (a preencher pela instituição)',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(4,'institution','institution.registration_info','','text','Autorização/registo junto das entidades competentes (a preencher pela instituição)',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(5,'institution','institution.nuit','','string','NUIT da instituição',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(6,'institution','institution.address','','string','Endereço',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(7,'institution','institution.phone','','string','Telefone',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(8,'institution','institution.email','','string','Email de contacto',NULL,'2026-10-16 12:47:09','2026-10-16 12:47:09'),(9,'institution','institution.whatsapp','','string','WhatsApp',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(10,'institution','institution.hours','Segunda a sexta, 08:00–16:30','string','Horário de atendimento',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(11,'content','content.hero_title','Crédito simples, gestão inteligente.','string','Título principal (página inicial)',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(12,'content','content.hero_subtitle','Solicite o seu microcrédito online, acompanhe o pedido em tempo real e faça a gestão das suas prestações num só lugar.','text','Subtítulo (página inicial)',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(13,'content','content.about','<p>O SumbaneCredit é uma plataforma de gestão de microcrédito que permite à instituição atender os seus clientes de forma rápida, transparente e próxima — desde a simulação e o pedido até à liquidação do empréstimo.</p><p><em>Texto de exemplo: personalize em Definições › Conteúdos do website.</em></p>','html','Sobre nós',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(14,'content','content.mission','Facilitar o acesso a crédito responsável, com condições claras e acompanhamento próximo de cada cliente. (Texto de exemplo)','text','Missão',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(15,'content','content.vision','Ser uma referência em microcrédito digital, transparente e centrado nas pessoas. (Texto de exemplo)','text','Visão',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(16,'content','content.values','Transparência\nResponsabilidade\nProximidade\nConfidencialidade\nRigor','text','Valores (um por linha)',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(17,'content','content.how_it_works','<p>Antes de submeter o pedido, simule as condições e confirme que a prestação se ajusta ao seu orçamento. Mantenha os seus contactos actualizados para receber avisos de vencimento.</p>','html','Como funciona',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(18,'content','content.privacy_policy','<p><strong>Modelo de referência — deve ser revisto e validado juridicamente pela instituição antes da publicação, à luz da legislação moçambicana aplicável.</strong></p>\n<h2>1. Responsável pelo tratamento</h2><p>A instituição identificada no rodapé deste website é responsável pelo tratamento dos dados pessoais recolhidos através da plataforma.</p>\n<h2>2. Dados recolhidos</h2><p>Dados de identificação (nome, documento de identificação, NUIT, data de nascimento), contactos, morada, situação profissional e rendimentos, documentos carregados, dados dos pedidos e empréstimos, pagamentos e registos de acesso.</p>\n<h2>3. Finalidades</h2><ul><li>Análise e gestão de pedidos de crédito e de contratos;</li><li>Identificação do cliente e cumprimento de obrigações legais, incluindo prevenção do branqueamento de capitais;</li><li>Gestão de pagamentos, cobranças e comunicações sobre o contrato;</li><li>Segurança da plataforma e auditoria.</li></ul>\n<h2>4. Conservação</h2><p>Os dados são conservados pelo período necessário às finalidades e aos prazos legais de conservação documental aplicáveis.</p>\n<h2>5. Partilha</h2><p>Os dados não são vendidos. Podem ser comunicados a entidades com quem a instituição contrate serviços (ex.: prestadores de pagamento) ou a autoridades, nos termos da lei.</p>\n<h2>6. Segurança</h2><p>Os documentos são guardados em armazenamento privado, o acesso é controlado por perfis e permissões e as operações relevantes são auditadas.</p>\n<h2>7. Direitos</h2><p>O titular pode pedir o acesso e a rectificação dos seus dados através dos contactos da instituição ou do suporte no portal.</p>','html','Política de privacidade',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(19,'content','content.terms','<p><strong>Modelo de referência — deve ser revisto e validado juridicamente pela instituição antes da publicação.</strong></p>\n<h2>1. Objecto</h2><p>Estes termos regulam a utilização do website e do portal do cliente. A utilização da plataforma não constitui, por si só, concessão de crédito.</p>\n<h2>2. Simulações</h2><p>As simulações são indicativas e não constituem aprovação nem proposta contratual. As condições finais constam do contrato.</p>\n<h2>3. Pedidos de crédito</h2><p>O cliente declara que as informações prestadas são verdadeiras. A instituição pode solicitar informação adicional e decidir sobre a concessão nos termos da sua política de crédito.</p>\n<h2>4. Pagamentos</h2><p>Os comprovativos submetidos no portal só são considerados pagamentos depois de confirmados pela instituição.</p>\n<h2>5. Conta e segurança</h2><p>O cliente é responsável pela confidencialidade das suas credenciais e deve comunicar qualquer utilização indevida.</p>','html','Termos e condições',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(20,'finance','finance.allocation_order','penalty,fee,interest,principal','string','Ordem de imputação dos pagamentos',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(21,'finance','finance.due_reminder_days','3','number','Dias de antecedência do aviso de vencimento',NULL,'2026-10-16 12:47:10','2026-10-16 12:47:10'),(22,'finance','finance.require_kyc_for_disbursement','1','boolean','Exigir identificação verificada antes do desembolso',NULL,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(23,'finance','finance.require_distinct_disbursement_authorizer','1','boolean','Autorização do desembolso por utilizador diferente do requerente',NULL,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(24,'finance','finance.collection_auto_assign','1','boolean','Atribuir cobranças ao agente do empréstimo',NULL,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(25,'uploads','uploads.max_kb','5120','number','Tamanho máximo de cada ficheiro (KB)',NULL,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(26,'security','security.require_2fa_staff','0','boolean','Exigir autenticação de dois factores aos funcionários',NULL,'2026-10-16 12:47:11','2026-10-16 12:47:11'),(27,'notifications','notifications.sms_enabled','0','boolean','Enviar SMS (requer prestador configurado)',NULL,'2026-10-16 12:47:11','2026-10-16 12:47:11');
