INSERT INTO `testimonials` VALUES (1,'Lurdes M.','Vendedora, Mercado Xipamanine','Consegui reforçar o stock da banca e acompanhar as prestações pelo telemóvel.',1,1,'2026-04-16 08:33:00','2026-04-16 08:33:00'),(2,'Armando C.','Electricista, Matola','A simulação mostrou exactamente o valor que ia pagar. Sem surpresas.',1,1,'2026-04-16 08:33:00','2026-04-16 08:33:00'),(3,'Graça T.','Costureira, Beira','Fui avisada antes de cada vencimento e recebi os recibos no portal.',1,1,'2026-04-16 08:33:00','2026-04-16 08:33:00');
